import numpy as np
from scipy.optimize import least_squares
rng=np.random.default_rng(1)
forms={
 'x^p t /(1+a x)': (lambda p: p[5]*x**p[6]*t/(1+p[7]*x), 8),
 'x^p t^q exp(-a x)': (lambda p: p[5]*x**p[6]*t**p[7]*np.exp(-p[8]*x), 9),
 'x^p t^q /(1+a x)': (lambda p: p[5]*x**p[6]*t**p[7]/(1+p[8]*x), 9),
 'x^p t^q (1+a x)': (lambda p: p[5]*x**p[6]*t**p[7]*(1+p[8]*x), 9),
}
for name,(g,n) in forms.items():
    best=None
    for s in range(40):
        p0=list(np.r_[rng.normal()*2, rng.normal()*3, rng.uniform(0.5,5), rng.normal()*2, rng.uniform(0.01,1), rng.normal(), rng.uniform(0,1.5), rng.uniform(0.5,1.5), rng.uniform(0,2)][:n])
        def mm(p):
            return p[0]*v**2 + p[1]*np.sin(p[2]*np.sqrt(v)) + p[3]*np.exp(-p[4]*t**2)*v + g(p)
        try:
            r=least_squares(lambda p: mm(p)-dv_dt, p0)
            if np.isfinite(r.cost) and (best is None or r.cost<best.cost): best=r
        except Exception: pass
    print(name, np.round(best.x,4), np.mean(best.fun**2)/np.var(dv_dt))

